<div class="card"><h2 class="section-title">Akun Siswa</h2><div class="form-grid"><div class="field"><label>Nama Lengkap *</label><input name="name" value="{{ old('name',$student?->user?->name) }}" required></div><div class="field"><label>Email Login *</label><input type="email" name="email" value="{{ old('email',$student?->user?->email) }}" required></div><div class="field"><label>{{ $student?'Password Baru':'Password *' }}</label><input type="password" name="password" {{ $student?'':'required' }}><small>{{ $student?'Kosongkan jika tidak diubah.':'Minimal 8 karakter.' }}</small></div><div class="field"><label>Konfirmasi Password</label><input type="password" name="password_confirmation" {{ $student?'':'required' }}></div></div></div>
<div class="card"><h2 class="section-title">Profil Siswa</h2><div class="form-grid"><div class="field"><label>NIS</label><input name="nis" value="{{ old('nis',$student?->nis) }}"></div><div class="field"><label>NISN</label><input name="nisn" value="{{ old('nisn',$student?->nisn) }}"></div><div class="field"><label>Jenis Kelamin</label><select name="gender"><option value="">- Pilih -</option><option value="L" @selected(old('gender',$student?->gender)==='L')>Laki-laki</option><option value="P" @selected(old('gender',$student?->gender)==='P')>Perempuan</option></select></div><div class="field"><label>No. HP</label><input name="phone" value="{{ old('phone',$student?->phone) }}"></div><div class="field"><label>Tempat Lahir</label><input name="birth_place" value="{{ old('birth_place',$student?->birth_place) }}"></div><div class="field"><label>Tanggal Lahir</label><input type="date" name="birth_date" value="{{ old('birth_date',$student?->birth_date?->format('Y-m-d')) }}"></div><div class="field full"><label>Alamat</label><textarea name="address">{{ old('address',$student?->address) }}</textarea></div></div></div>
